 */

class DatabaseController
{
    private function configPath(): string
    {
        return __DIR__ . '/../../config/database.php';
    }

    private function currentConfig(): ?array
    {
        $p = $this->configPath();
        if (!is_file($p)) {
            return null;
        }
        $c = require $p;
        return is_array($c) ? $c : null;
    }

    /**
     * Returns the logged-in user row, or null after emitting a 401 response.
     */
    private function requireAuth(): ?array
    {
        $userId = $_SESSION['user_id'] ?? null;
        if (!$userId) {
            Response::json(['error' => 'Unauthorized'], 401);
            return null;
        }
        $db = Database::getConnection();
        $stmt = $db->prepare('SELECT id, username, is_admin FROM users WHERE id = :id AND deleted_at IS NULL');
        $stmt->execute(['id' => $userId]);
        $user = $stmt->fetch();
        if (!$user) {
            Response::json(['error' => 'Unauthorized'], 401);
            return null;
        }
        return $user;
    }

    /**
     * Returns the logged-in admin's user row, or null after emitting the
     * appropriate 401/403 response.
     */
    private function requireAdmin(): ?array
    {
        $userId = $_SESSION['user_id'] ?? null;
        if (!$userId) {
            Response::json(['error' => 'Unauthorized'], 401);
            return null;
        }
        $db = Database::getConnection();
        $stmt = $db->prepare('SELECT id, username, password_hash, is_admin FROM users WHERE id = :id');
        $stmt->execute(['id' => $userId]);
        $user = $stmt->fetch();
        if (!$user || (int) ($user['is_admin'] ?? 0) !== 1) {
            Response::json(['error' => 'Only an admin can change database settings'], 403);
            return null;
        }
        return $user;
    }

    /**
     * GET /api/settings/database — current connection summary (never the
     * password).
     */
    public function info(): void
    {
        $auth = $this->requireAuth();
        if (!$auth) {
            return;
        }

        $cfg = $this->currentConfig();
        if (!$cfg) {
            Response::json(['configured' => false]);
            return;
        }
        $useBundled = !empty($cfg['use_bundled']);
        $payload = [
            'configured'        => true,
            'engine'            => $useBundled ? 'bundled' : 'external',
            'host'              => $cfg['host'] ?? '',
            'port'              => (int) ($cfg['port'] ?? 3306),
            'database'          => $cfg['database'] ?? '',
            'username'          => $cfg['username'] ?? '',
            'use_tls'           => !empty($cfg['use_tls']),
            'use_bundled'       => $useBundled,
            'bundled_available' => BundledMaria::binariesAvailable(),
            'system_version'    => Version::SCHEMA,
            'app_version'       => Version::APP,
            'db_version'        => null,
            'version_state'     => 'unknown',
        ];
        try {
            $st = Version::status(Database::getConnection());
            $payload['db_version'] = $st['db'];
            $payload['version_state'] = $st['state'];
        } catch (\Throwable $e) {
            error_log("Suppressed exception in " . __METHOD__ . ": " . $e->getMessage());
        }
        Response::json($payload);
    }

    /**
     * POST /api/settings/database/switch — connect the app to a different
     * MySQL / MariaDB server. Creates the database if missing and applies the
     * schema only when the target is empty (so an existing database is never
     * clobbered). The session is invalidated afterwards — the user signs in
     * again against the new database.
     */
    public function switchDatabase(array $data): void
    {
        $admin = $this->requireAdmin();
        if (!$admin) {
            return;
        }

        $adminPassword = $data['admin_password'] ?? '';
        if ($adminPassword === '' || !password_verify($adminPassword, $admin['password_hash'])) {
            Response::json(['error' => 'Your admin password is required to switch databases'], 403);
            return;
        }

        // Spinning up the bundled daemon can take a few seconds on first run.
        @set_time_limit(120);

        if (!empty($data['use_bundled'])) {
            // Switch TO the built-in portable MariaDB.
            if (!BundledMaria::binariesAvailable()) {
                Response::json(['error' => 'The built-in database is not bundled in this build'], 400);
                return;
            }
            try {
                $port = BundledMaria::ensureStarted();
            } catch (\Throwable $e) {
                error_log("BundledMaria failed to start in " . __METHOD__ . ": " . $e->getMessage());
                Response::json(['error' => 'Failed to start built-in database daemon. Please check server logs.'], 400);
                return;
            }
