                'database'    => BundledMaria::DB_NAME,
                'username'    => 'root',
                'password'    => '',
                'charset'     => 'utf8mb4',
                'use_tls'     => false, // loopback to a private daemon — no TLS
                'use_bundled' => true,
            ];
        } else {
            // Switch TO an external MySQL / MariaDB.
            $config = [
                'host'        => trim($data['host'] ?? ''),
                'port'        => (int) ($data['port'] ?? 3306),
                'database'    => trim($data['database'] ?? ''),
                'username'    => trim($data['username'] ?? ''),
                'password'    => $data['password'] ?? '',
                'charset'     => 'utf8mb4',
                'use_tls'     => !empty($data['use_tls']),
                'use_bundled' => false,
            ];
            if ($config['host'] === '' || $config['database'] === '' || $config['username'] === '') {
                Response::json(['error' => 'Host, database, and username are required'], 400);
                return;
