        if (!$hasAdmin) {
            require_once __DIR__ . '/../Services/SetupProgressService.php';
            // Issue Step 2 token so the setup wizard properly runs /api/setup/preset,
            // populating settings row 1 and naming the dual cash vaults before admin creation.
            $setupToken = SetupProgressService::issueStepToken(2);
        }

        Response::json([
            'ok'          => true,
            'has_admin'   => $hasAdmin,
            'setup_token' => $setupToken,
            'engine'      => $config['use_bundled'] ? 'bundled' : 'external',
            'message'     => $hasAdmin
                ? ($config['use_bundled'] ? 'Switched to the built-in database. Please sign in again.' : 'Database switched. Please sign in again.')
                : ($config['use_bundled'] ? 'Switched to the built-in database. Please create your super admin account.' : 'Database switched. Please create your super admin account.'),
        ]);
    }

    /**
     * POST /api/settings/database/verify — manual "Verify & build" against the
     * CURRENT connection. Same idea as the automatic check on switch/creation,
     * but on demand and with a detailed report:
     *   - data at/behind this build → builds any missing tables (idempotent) and
     *     replays pending migrations, reporting what changed;
     *   - data from a NEWER build  → reports it ("this database is above me")
     *     without changing anything (we can't safely migrate down).
     * Admin session required. Non-destructive — it only ever ADDS what's missing.
     */
    public function verifyAndBuild(array $data): void
    {
        $admin = $this->requireAdmin();
        if (!$admin) {
            return;
        }

        // Building tables on a large database can take a moment.
        @set_time_limit(120);

        try {
            $db = Database::getConnection();
        } catch (\Throwable $e) {
            error_log("Database connection failure in " . __METHOD__ . ": " . $e->getMessage());
            Response::json(['error' => 'Could not connect to the database. Please check server configuration.'], 400);
            return;
        }

        try {
            Version::ensureTable($db);
            $before = Version::status($db);

            // Data made by a newer build — we can't safely build/migrate down.
            if ($before['state'] === 'ahead') {
                Response::json([
                    'ok'             => true,
                    'state'          => 'ahead',
                    'db_version'     => $before['db'],
                    'system_version' => Version::SCHEMA,
                    'created_tables' => [],
                    'applied'        => [],
                    'message'        => "This database is from version {$before['db']}, which is above this system (version " . Version::SCHEMA . "). "
                        . "This system can only use the tables it understands — some newer features and data may be unavailable. "
                        . "Update this system to version {$before['db']} for full compatibility.",
                ]);
                return;
            }

            // Seed a legacy (no version row) database at the baseline.
            if ($before['db'] === null) {
                Version::setDbVersion($db, Version::BASELINE);
            }

            // Build any missing tables AND columns (idempotent, additive — never
            // drops or alters existing columns or touches row data).
            $report = buildMissingStructure($db);
            $created = $report['created_tables'];
            $addedColumns = $report['added_columns'];
            $failed = $report['failed'];

            // Replay any pending forward migrations.
            $applied = Version::migrateUp($db);
            $after = Version::status($db);

            $parts = [];
            if ($created) {
                $parts[] = count($created) . ' missing table(s) built: ' . implode(', ', $created);
            }
            if ($addedColumns) {
                $parts[] = count($addedColumns) . ' missing column(s) added: ' . implode(', ', $addedColumns);
            }
            if ($applied) {
                $parts[] = 'migration(s) applied for version(s) ' . implode(', ', $applied);
            }
            if (!$parts) {
                $parts[] = 'everything is already up to date';
            }

            try {
                SystemLog::write('settings', 'database_verified', null, null, json_encode([
                    'created_tables' => $created,
                    'added_columns'  => $addedColumns,
                    'applied'        => $applied,
                    'failed'         => $failed,
                    'state'          => $after['state'],
                ]));
            } catch (\Throwable $e) {
            error_log("Suppressed exception in " . __METHOD__ . ": " . $e->getMessage());
        }

            Response::json([
                'ok'             => true,
                'state'          => $after['state'],
                'db_version'     => $after['db'],
                'system_version' => Version::SCHEMA,
                'created_tables' => $created,
                'added_columns'  => $addedColumns,
                'failed'         => $failed,
                'applied'        => $applied,
                'message'        => 'Verification complete — ' . implode('; ', $parts) . '.',
            ]);
        } catch (\Throwable $e) {
            error_log("Database verification failed in " . __METHOD__ . ": " . $e->getMessage());
            Response::json(['error' => 'Database verification failed. Please check server logs.'], 400);
        }
    }

    /**
     * POST /api/settings/database/delete-bundled — stop and wipe the portable
     * built-in MariaDB (data + generated config), returning the app to the
     * fresh setup wizard. Refuses unless this install actually uses the
     * bundled database. Admin password + a typed "DELETE" confirmation
     * required.
     */
    public function deleteBundled(array $data): void
    {
        $admin = $this->requireAdmin();
        if (!$admin) {
            return;
        }

        $cfg = $this->currentConfig();
        if (!$cfg || empty($cfg['use_bundled'])) {
            Response::json(['error' => 'Delete is only available when using the built-in database'], 400);
            return;
        }

        $adminPassword = $data['admin_password'] ?? '';
        if ($adminPassword === '' || !password_verify($adminPassword, $admin['password_hash'])) {
            Response::json(['error' => 'Your admin password is required'], 403);
            return;
        }
        if (($data['confirm'] ?? '') !== 'DELETE') {
            Response::json(['error' => 'Type DELETE to confirm'], 400);
            return;
        }

        // Stop the daemon (synchronous) so its data files unlock, then wipe.
        try {
            BundledMaria::shutdown();
        } catch (\Throwable $e) {
            error_log("Suppressed exception in " . __METHOD__ . ": " . $e->getMessage());
        }
        Database::reset();

        $runtime = BundledMaria::rootDir() . '/runtime';
        self::rrmdir($runtime . '/data');
        @unlink($runtime . '/port.txt');
        @unlink($runtime . '/my.cnf');
        @unlink($runtime . '/server.err');

        // Remove the generated config so /api/setup/db/status reports unconfigured
        // and the setup wizard reappears on next load.
        @unlink($this->configPath());

        Response::json([
            'ok'      => true,
            'message' => 'Built-in database deleted. The app will restart setup.',
        ]);
    }

    /** Recursively delete a directory (best-effort; ignores locked files). */
    private static function rrmdir(string $dir): void
    {
        if (!is_dir($dir)) {
            return;
        }
        foreach (scandir($dir) ?: [] as $item) {
            if ($item === '.' || $item === '..') {
                continue;
            }
            $path = $dir . DIRECTORY_SEPARATOR . $item;
            if (is_dir($path)) {
                self::rrmdir($path);
            } else {
                @unlink($path);
            }
        }
        @rmdir($dir);
    }
}

